#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m, k, d, i = 1;
    cin >> n >> m >> k;

    string s;
    cin >> s >> s;

    d = s[0] == 'h' ? -1 : 1;

    for (char c; cin >> c; ++i) {
        m < k && m > 1 ? --m : m > k && m < n ? ++m : 1;
        (k += d) > n && (k -= 2, d = -1);
        k || (k += 2, d = 1);

        if (c - '0')
            m = k == 1 || d < 0 && k < n ? n : 1;

        if (k == m)
            return cout << "Controller " << i, 0;
    }

    cout << "Stowaway";
}

